add_action( 'woocommerce_after_add_to_cart_form', 'perfectpixel_dispatch_date_notice' );

function perfectpixel_dispatch_date_notice() {
	global $product;
	if ( ! $product || ! $product->is_in_stock() || $product->is_virtual() ) {
		return;
	}
	$now     = current_datetime();
	$weekday = (int) $now->format( 'N' ); // 1 = Monday ... 7 = Sunday.
	if ( $weekday <= 5 && (int) $now->format( 'G' ) < (int) '{{dispatch_cutoff_hour}}' ) {
		$text = esc_html( '{{dispatch_today_text}}' );
	} else {
		$next = $now->modify( '+1 day' );
		while ( (int) $next->format( 'N' ) > 5 ) {
			$next = $next->modify( '+1 day' );
		}
		$tomorrow = $now->modify( '+1 day' )->format( 'Y-m-d' ) === $next->format( 'Y-m-d' );
		$day      = $tomorrow ? '{{dispatch_tomorrow_word}}' : wp_date( 'l', $next->getTimestamp() );
		$text     = str_replace( '{day}', esc_html( $day ), esc_html( '{{dispatch_later_text}}' ) );
	}
	echo '<p class="perfectpixel-dispatch-notice" style="margin-top:1em">&#128666; ' . $text . '</p>';
}
